-- Al aplicar la migración, desplazar las actividades de ejemplo al futuro para
-- que sigan apareciendo como "próximas actividades" en la app móvil.
UPDATE activities a SET
    start_at = now() + (d.rn * interval '3 days') + interval '10 hours',
    end_at   = now() + (d.rn * interval '3 days') + interval '12 hours'
FROM (
    SELECT id, row_number() OVER (ORDER BY created_at, id) AS rn
    FROM activities
    WHERE id IN ('7268a457-2237-4491-9c5f-5f6805081b02', '3ab1d734-b523-464f-809c-503c0aebbcab', '0161fad0-25e4-45db-9274-66829c2e636b', '727693ca-282a-4cd8-97a0-6cc1ac4b0937', 'ee35fdf7-4489-4a50-a1d4-0c3ca81a5dbf', '4ff693cd-a350-49af-a17c-56ae79478c2c')
) d
WHERE a.id = d.id;

UPDATE activity_reminders r
SET remind_at = (SELECT start_at - interval '1 day' FROM activities WHERE id = r.activity_id)
WHERE r.activity_id IN ('7268a457-2237-4491-9c5f-5f6805081b02', '3ab1d734-b523-464f-809c-503c0aebbcab', '0161fad0-25e4-45db-9274-66829c2e636b', '727693ca-282a-4cd8-97a0-6cc1ac4b0937', 'ee35fdf7-4489-4a50-a1d4-0c3ca81a5dbf', '4ff693cd-a350-49af-a17c-56ae79478c2c');
